import{_ as t,o as d,c as r,ag as a}from"./chunks/framework.CrXGS008.js";const b=JSON.parse('{"title":"Einstellungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/repair-station-business/settings.md","filePath":"de/repair-station-business/settings.md"}'),n={name:"de/repair-station-business/settings.md"};function i(o,e,s,l,h,c){return d(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="einstellungen" tabindex="-1">Einstellungen <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Einstellungen&quot;">​</a></h1><p>Jede Einstellung der Repair Station Business wird in <code>/nay</code> bearbeitet, auf der Seite <strong>Repair Station Business</strong> (Scope <code>nay_repair_business.config</code>). Änderungen werden in der Datenbank gespeichert und sofort für alle Spieler übernommen. <code>config.lua</code> enthält optionale Startwerte: Sie gelten, bis eine Einstellung in <code>/nay</code> geändert wird, und <strong>Zurücksetzen</strong> geht auf sie zurück.</p><p>Die Spalte <strong>In /nay</strong> zeigt den Namen, der im Panel angezeigt wird. Der Schlüssel ist der Name, den <code>config.lua</code> und die <a href="/de/nay-lib/api">HTTP-API</a> verwenden.</p><h2 id="allgemein" tabindex="-1">Allgemein <a class="header-anchor" href="#allgemein" aria-label="Permalink to &quot;Allgemein&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Aktiviert</td><td><code>Enabled</code></td><td>an / aus</td><td>an</td><td>Schaltet die Besitzfunktionen ein oder aus. Ausgeschaltet verhalten sich die Stationen wie einfache Repair Stations. Besitzer können weiterhin Geld aus der Kasse nehmen oder ihre Station verkaufen.</td></tr><tr><td>Stationen zum Verkauf ohne Besitzer</td><td><code>UnownedMode</code></td><td><code>open</code> oder <code>closed</code></td><td><code>open</code></td><td>Offen: Spieler können dort weiterhin reparieren. Geschlossen: Die Station lehnt Reparaturen ab, bis jemand sie kauft.</td></tr></tbody></table><h2 id="besitz" tabindex="-1">Besitz <a class="header-anchor" href="#besitz" aria-label="Permalink to &quot;Besitz&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Stationen zum Verkauf</td><td><code>Purchasable</code></td><td>Liste, bis zu 64</td><td>keine</td><td>Stationen, die Spieler kaufen können. Verwalte sie im Spiel über das Admin-Panel.</td></tr><tr><td>Stationen pro Spieler</td><td><code>MaxStationsPerPlayer</code></td><td>Zahl, 1 bis 16</td><td>1</td><td>Wie viele Stationen ein Spieler besitzen kann.</td></tr><tr><td>Kaufkonto</td><td><code>BuyAccount</code></td><td><code>cash</code> oder <code>bank</code></td><td><code>bank</code></td><td>Konto, von dem der Kaufpreis abgebucht wird.</td></tr><tr><td>Rückkauf (%)</td><td><code>SellBackPercent</code></td><td>Zahl, 0 bis 100</td><td>50</td><td>Anteil des Kaufpreises, der erstattet wird, wenn der Besitzer die Station verkauft oder verliert.</td></tr><tr><td>Inaktivitätsgrenze (Tage)</td><td><code>InactivityDays</code></td><td>Zahl, 0 bis 90</td><td>14</td><td>Ein Besitzer, der das Tablet so lange nicht öffnet, verliert die Station und bekommt eine Erstattung. 0 schaltet das aus.</td></tr></tbody></table><h2 id="lager" tabindex="-1">Lager <a class="header-anchor" href="#lager" aria-label="Permalink to &quot;Lager&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Lagerkapazität</td><td><code>Capacity</code></td><td>Zahl, 10 bis 10000</td><td>100</td><td>Maximale Anzahl Teile, die eine Station aufnehmen kann.</td></tr><tr><td>Teile für den Motor</td><td><code>PartsEngine</code></td><td>Zahl, 0 bis 100</td><td>2</td><td>Teile, die eine Leistung zur Motorreparatur verbraucht.</td></tr><tr><td>Teile für die Karosserie</td><td><code>PartsBody</code></td><td>Zahl, 0 bis 100</td><td>3</td><td>Teile, die eine Leistung zur Karosseriereparatur verbraucht.</td></tr><tr><td>Teile für die Reifen</td><td><code>PartsTyres</code></td><td>Zahl, 0 bis 100</td><td>1</td><td>Teile, die eine Leistung zur Reifenreparatur verbraucht.</td></tr><tr><td>Auffüllmodus</td><td><code>RestockMode</code></td><td><code>purchase</code>, <code>items</code> oder <code>both</code></td><td><code>both</code></td><td>Wie Besitzer das Lager auffüllen.</td></tr><tr><td>Preis pro Teil</td><td><code>PartPrice</code></td><td>Zahl, 0 bis 100000</td><td>40</td><td>Wird beim Kauf von Teilen von der Bank des Besitzers bezahlt.</td></tr><tr><td>Teile-Gegenstand</td><td><code>PartItem</code></td><td>Text, 1 bis 64 Zeichen</td><td><code>repair_parts</code></td><td>Inventargegenstand, der zum Auffüllen abgegeben wird.</td></tr><tr><td>Teile pro Gegenstand</td><td><code>PartsPerItem</code></td><td>Zahl, 1 bis 100</td><td>5</td><td>Teile, die ein Gegenstand dem Lager hinzufügt.</td></tr><tr><td>Warnung bei niedrigem Lager</td><td><code>LowStockThreshold</code></td><td>Zahl, 0 bis 10000</td><td>10</td><td>Der Besitzer wird gewarnt, wenn das Lager unter diese Zahl fällt. 0 schaltet die Warnung aus.</td></tr></tbody></table><h2 id="preise" tabindex="-1">Preise <a class="header-anchor" href="#preise" aria-label="Permalink to &quot;Preise&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Niedrigster Preis (%)</td><td><code>MinPricePercent</code></td><td>Zahl, 10 bis 100</td><td>50</td><td>Niedrigster Anteil des Leistungspreises, den ein Besitzer festlegen kann.</td></tr><tr><td>Höchster Preis (%)</td><td><code>MaxPricePercent</code></td><td>Zahl, 100 bis 500</td><td>200</td><td>Höchster Anteil des Leistungspreises, den ein Besitzer festlegen kann.</td></tr><tr><td>Steuer (%)</td><td><code>TaxPercent</code></td><td>Zahl, 0 bis 90</td><td>10</td><td>Anteil jeder Reparaturzahlung, der nicht in die Kasse gelangt.</td></tr></tbody></table><h2 id="karte" tabindex="-1">Karte <a class="header-anchor" href="#karte" aria-label="Permalink to &quot;Karte&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Blip-Farbe einer eigenen Station</td><td><code>OwnedBlipColor</code></td><td>Zahl, 0 bis 85</td><td>2</td><td>Blip-Farbe der Stationen, die dir gehören, auf deiner Karte.</td></tr><tr><td>Blip-Farbe einer Station zum Verkauf</td><td><code>ForSaleBlipColor</code></td><td>Zahl, 0 bis 85</td><td>5</td><td>Blip-Farbe der Stationen zum Verkauf.</td></tr></tbody></table><p>Einträge von <strong>Stationen zum Verkauf</strong>:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th></tr></thead><tbody><tr><td>Stations-ID</td><td><code>StationId</code></td><td>8 Zeichen (0 bis 9, a bis f), wie im Editor der Repair Station.</td></tr><tr><td>Preis</td><td><code>Price</code></td><td>Zahl, 0 bis 100000000</td></tr></tbody></table><p>Die Prozentsätze des Besitzers (<code>MinPricePercent</code>, <code>MaxPricePercent</code>) gelten für den Preis jeder Leistung, vor den Job-Rabatten. Die Steuer (<code>TaxPercent</code>) wird von jeder Reparaturzahlung abgezogen, bevor sie in die Kasse gelangt.</p>',16)])])}const g=t(n,[["render",i]]);export{b as __pageData,g as default};
